def dec_to_any_string(n, radix):
    converted_number = []
    while n != 0:
        if n >= radix and 16 > radix > 2:
            R = n % radix
            if R >= 10:
                R = chr(R + 55)  # Convert 10-15 to 'A'-'F'
            n = n // radix
            converted_number.insert(0, R)
        else:
            n = n // radix
            converted_number.insert(0, str(n % radix))
    new_num = ''.join(map(str, converted_number))
    if new_num > 0:
        print("%s base 10 is %s in base %s" % (n, new_num, radix))
    return new_num
